CREATE OR REPLACE FUNCTION ECAMS.SVRNAME_CHECK
(SVRIP varchar2)
return VARCHAR2
IS
    V_SVRNM     CMM0031.CM_SVRNAME%TYPE;


CURSOR  SYSSVRNM IS
    SELECT  A.CM_SVRNAME
      FROM  CMM0031 A
          , CMM0030 B
     WHERE  A.CM_SVRIP = SVRIP
       AND  A.CM_CLOSEDT IS NULL
       AND  A.CM_SVRCD IN ('03','05')
       AND  A.CM_SYSCD = B.CM_SYSCD
       AND  B.CM_CLOSEDT IS NULL
     ORDER  BY  A.CM_SYSCD, A.CM_SEQNO;

BEGIN
    V_SVRNM := '----------';

    For Lst In SYSSVRNM  Loop
        V_SVRNM := Lst.CM_SVRNAME;
        EXIT;
    End Loop;

    return  V_SVRNM;

END ;